<div class="table-wrap"><table><thead><tr><th>Trip</th><th>Category</th><th>Label</th><th>Amount</th><th>Action</th></tr></thead><tbody><?php foreach ($expenses as $expense): ?><tr><td><?php echo h($expense['trip_name']); ?></td><td><?php echo h($expense['category']); ?></td><td><?php echo h($expense['label']); ?></td><td>EUR <?php echo number_format((float)$expense['amount'], 2); ?></td><td><form method="post"><input type="hidden" name="action" value="delete_expense"><input type="hidden" name="id" value="<?php echo $expense['id']; ?>"><button class="danger" type="submit">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div>
